`timescale 1ns / 1ps

module d_latch_tb;

    // Signals
    reg enable;
    reg reset;
    reg d;
    wire q;

    // Instantiate the Unit Under Test (UUT)
    d_latch uut (
        .enable(enable), 
        .reset(reset), 
        .d(d), 
        .q(q)
    );

    initial begin
        // --- VCD Waveform Generation for GTKWave ---
        $dumpfile("d_latch_wave.vcd");
        $dumpvars(0, d_latch_tb);

        // Initialize signals
        enable = 0;
        reset = 1;
        d = 0;

        // Apply reset
        #10;
        reset = 0;

        // Test D input changes while enable is LOW (should hold state)
        #10 d = 1;
        #10 d = 0;

        // Turn enable HIGH (latch becomes transparent)
        #10 enable = 1;
        #10 d = 1;
        #10 d = 0;
        #10 d = 1;

        // Turn enable LOW (latch holds value)
        #10 enable = 0;
        #10 d = 0; // Changing D should not affect Q now
        #10 d = 1;

        // Finish simulation
        #20;
